	private String name;
	private String normalizeName;
	private String conceptCode;
	private String expression;
	private byte type;
	
	private AgreementPayment(String name, String normalizeName, String conceptCode, String expression, byte type) {
		this.name = name;
		this.normalizeName = normalizeName;
		this.conceptCode = conceptCode;
		this.expression = expression;
		this.type = type;
	}
	
	public static AgreementPayment safeValueOf(String name) {
		if (AonStringUtils.isBlank(name)) {
			return null;
		}
		try {
			return AgreementPayment.valueOf(name);
		} catch (IllegalArgumentException e) {
			return null;
		}
	}

	public String getName() {
		return name;
	}
	
	public String getNormalizeName() {
		return normalizeName;
	}

	public String getConceptCode() {
		return conceptCode;
	}

	public String getExpression() {
		return expression;
	}
	
	public byte getType() {
		return type;
	}
	
	public static void main(String[] args) {
		List<AgreementPayment> valueList = Arrays.asList(AgreementPayment.values());
		valueList.sort(new Comparator<AgreementPayment>() {

			@Override
			public int compare(AgreementPayment o1, AgreementPayment o2) {
				return o1.getName().compareTo(o2.getName());
			}
		});
		
		for(AgreementPayment agreementPayment : valueList) {
			System.out.println("put(\"" + agreementPayment.name + "\", \"" + agreementPayment.conceptCode + "\");");
//			System.out.println(agreementPayment.name + "(\"" + agreementPayment.name + "\", \"" + agreementPayment.normalizeName + "\""
//					 + ", \"" + agreementPayment.conceptCode + "\"" + ", \"" + agreementPayment.expression + "\""
//					 + ", (byte)" + agreementPayment.type + "),");
		}
	}

	@Override
	public int compare(AgreementPayment o1, AgreementPayment o2) {
		return o1.getName().compareTo(o2.getName());
	}
	
